import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Asignacion } from '../entities/asignacion.entity';
import { Proyecto } from '../../proyectos/entities/proyecto.entity';
import { Colaborador } from '../../colaboradores/entities/colaborador.entity';

@Injectable()
export class AsignarColaboradorRepository {
  constructor(
    @InjectRepository(Asignacion) private readonly asignaciones: Repository<Asignacion>,
    @InjectRepository(Proyecto) private readonly proyectos: Repository<Proyecto>,
    @InjectRepository(Colaborador) private readonly colaboradores: Repository<Colaborador>
  ) {}

  buscarProyectoRepository(proyectoId: number) {
    return this.proyectos.findOneBy({ id: proyectoId });
  }

  buscarColaboradorRepository(colaboradorId: number) {
    return this.colaboradores.findOneBy({ id: colaboradorId });
  }

  async asignarColaboradorRepository(proyectoId: number, colaboradorId: number, rol: string) {
    const asignacion = { proyectoId, colaboradorId, rol };
    await this.asignaciones.insert(asignacion);
    return asignacion;
  }
}

import { ConflictException, Injectable, NotFoundException } from '@nestjs/common';
import { QueryFailedError } from 'typeorm';
import { AsignarColaboradorRepository } from './repository';

@Injectable()
export class AsignarColaboradorService {
  constructor(private readonly repository: AsignarColaboradorRepository) {}

  async asignarColaboradorService(proyectoId: number, colaboradorId: number, rol: string) {
    const proyecto = await this.repository.buscarProyectoRepository(proyectoId);
    const colaborador = await this.repository.buscarColaboradorRepository(colaboradorId);
    if (!proyecto || !colaborador) {
      throw new NotFoundException('No existe el proyecto o el colaborador');
    }

    try {
      return await this.repository.asignarColaboradorRepository(proyectoId, colaboradorId, rol);
    } catch (error) {
      if (error instanceof QueryFailedError && error.driverError.code === '23505') {
        throw new ConflictException('El colaborador ya está asignado a ese proyecto');
      }
      throw error;
    }
  }
}

import { Body, Controller, Param, Post } from '@nestjs/common';
import { AsignarColaboradorService } from './service';

@Controller('proyectos/:proyectoId/asignaciones')
export class AsignarColaboradorController {
  constructor(private readonly service: AsignarColaboradorService) {}

  @Post()
  asignar(@Param('proyectoId') proyectoId: string, @Body() datos: { colaboradorId: number; rol: string }) {
    return this.service.asignarColaboradorService(Number(proyectoId), datos.colaboradorId, datos.rol);
  }
}
